    SELECT 
        COALESCE(o.grandparent_org_name, o.org_name) AS account_name,
        SUM(s.pack_units) AS total_units
    FROM sales s
    JOIN organizations o ON s.org_id = o.org_id
    WHERE s.data_source = ''distributor'' 
      AND s.brand_flag = 1 
      AND s.drug_name = ''Zenovax''
      AND s.period_qtr = (SELECT period_qtr FROM sales ORDER BY transaction_date DESC LIMIT 1)
    GROUP BY 1
    ORDER BY total_units DESC
    LIMIT 3
)
