CREATE TABLE users (
    user_id             TEXT PRIMARY KEY,
    email               TEXT NOT NULL UNIQUE,
    full_name           TEXT NOT NULL,
    role                TEXT NOT NULL,       -- 'exec', 'director', 'ram'
    territory_name      TEXT,               -- assigned territory (RAM only)
    region_name         TEXT,               -- assigned region (Director + RAM)
    can_view_wac        INTEGER DEFAULT 0   -- 1 = can see WAC pricing data
);
CREATE TABLE zip_territory (
    zip                 TEXT PRIMARY KEY,
    state               TEXT NOT NULL,
    territory_number    TEXT NOT NULL,
    territory_name      TEXT NOT NULL,
    region_number       TEXT,
    region_name         TEXT
);
CREATE INDEX idx_sales_data_source ON sales(data_source, brand_flag);
CREATE INDEX idx_sales_mo_offset ON sales(mo_offset);
CREATE INDEX idx_sales_wk_offset ON sales(wk_offset);
CREATE INDEX idx_sales_org_id ON sales(org_id);
CREATE INDEX idx_sales_ndc ON sales(ndc);
CREATE INDEX idx_sales_drug_name ON sales(drug_name);
CREATE INDEX idx_sales_period_mo ON sales(period_mo);
CREATE INDEX idx_org_zip ON organizations(zip);
CREATE INDEX idx_org_grandparent ON organizations(grandparent_org_name);
CREATE INDEX idx_zip_territory ON zip_territory(territory_name, region_name);
CREATE INDEX idx_users_email ON users(email);
CREATE INDEX idx_sessions_user_id ON chat_sessions(user_id, updated_at);
CREATE INDEX idx_messages_session ON session_messages(session_id, created_at);
